using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}var t=DateTimeOffset.Parse("2025-01-01T00:00:00Z");var all=new[]{new Item("c",t),new Item("a",t),new Item("b",t),new Item("d",t.AddDays(-1))};C("C01",()=>{var a=Paginator.Page(all,null,null,2);var b=Paginator.Page(all,a[^1].CreatedAt,a[^1].Id,2);return a.Concat(b).Select(x=>x.Id).Distinct().Count()==4;});C("C02",()=>string.Join(',',Paginator.Page(all,null,null,3).Select(x=>x.Id))=="a,b,c");C("C03",()=>Paginator.Page(all,t,"b",5).First().Id=="c");C("C04",()=>Paginator.Page(all.Reverse(),null,null,4).Select(x=>x.Id).SequenceEqual(["a","b","c","d"]));C("C05",()=>{try{Paginator.Page(all,null,null,0);return false;}catch(ArgumentOutOfRangeException){return true;}});
